/// <summary>
/// MPJ_22902_CustomerNumbering
/// </summary>
public class METCreateCustNumSeqDialog extends RunBase
{
    protected   DialogRunBase               dialog;
    protected   DialogField                 dlgCreateCustomer, dlgBusinessUnit;
    protected   FormReferenceGroupControl   businessUnit;
    protected   RefRecId                    metBusinessUnitRecId;
    CustTable                               custTable;
    
}

Method.Source:
    /// <summary>
    /// calling the updateCustomerNumSeqRec method
    /// </summary>
    /// <param name = "_args">_args</param>
    public static void main(Args _args)
    {
        METCreateCustNumSeqDialog           dialogCreateCustNumSeqDialog;
        FormRun                             formRun = _args.caller();
        CustTable                           custTable = _args.record();
        
        dialogCreateCustNumSeqDialog = new METCreateCustNumSeqDialog();

        if (dialogCreateCustNumSeqDialog.prompt())
        {
            dialogCreateCustNumSeqDialog.parmCustTable(custTable);
            dialogCreateCustNumSeqDialog.runOperation();
        }
        else
        {
            formRun.close();
        }

    }

/// <summary>
/// Contains the code that does the actual job of the class.
/// </summary>
public void run()
{
    custTable.selectForUpdate(true);
    custTable.AccountNum =  METCreateCustNumSeqDialog::getCustomerNumSeqRec(metBusinessUnitRecId);
}

    /// <summary>
    /// get the customer number sequence
    /// </summary>
    /// <param name = "_metBusinessUnitRecId">Business unit</param>
    /// <returns>Number sequence</returns>
    public static CustAccount getCustomerNumSeqRec(RefRecId _metBusinessUnitRecId)
    {
        NumberSequenceCode      numberSequence, numberSeq;
        METBusinessUnit         metBusinessUnit     = METBusinessUnit::findRecId(_metBusinessUnitRecId);
        RefRecId                numberseqcust       = metBusinessUnit.NumberSequenceId;
        Integer                 businessPrefixValue = metBusinessUnit.BusinessPrefix;
        NumberSequenceTable     numberseqTable      = NumberSequenceTable::find(numberseqcust);
        METCheckDigitLogic      checkDigitLogic     = metBusinessUnit.CheckDigitLogic;
        int                     checkDigit;

        METCreateCustNumSeqDialog metCreateCustNumSeqDialog = new METCreateCustNumSeqDialog();

        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            numberSeq = NumberSeq::newGetNumFromId(numberseqTable.RecId).num();

            if (metBusinessUnit.EnableStatePrefix == NoYes::Yes)
            {
                numberSequence = int2Str(businessPrefixValue) + int2Str(metBusinessUnit.StatePrefix) + numberSeq;
            }
            else
            {
                numberSequence = int2Str(businessPrefixValue) + numberSeq;
            }
            
            if (checkDigitLogic == METCheckDigitLogic::PECCD1)
            {
                checkDigit = METCheckDigitLogicHelper::getCheckDigit_One(numberSeq);
            }
            else if (checkDigitLogic == METCheckDigitLogic::PECCD2)
            {
                checkDigit = METCheckDigitLogicHelper::getCheckDigit_Two(numberSeq);
            }
            else if (checkDigitLogic == METCheckDigitLogic::PECCD5)
            {
                checkDigit = METCheckDigitLogicHelper::checkDigit_Five(numberSeq);
            }
            
            if(checkDigitLogic != METCheckDigitLogic::None)
            {
                numberSequence =  numberSequence + int2Str(checkDigit);
            }
        }
            
        else
        {
            RefRecId                numberseqcustHWE = METCustParameters::Find().NumberSequenceId;
            NumberSequenceTable     numberseqTableHWE = NumberSequenceTable::find(numberseqcustHWE);
            
            numberSeq = NumberSeq::newGetNumFromId(numberseqTableHWE.RecId).num();

            if (METCustParameters::Find().CheckDigit == NoYes::Yes)
            {
                checkDigit = METCheckDigitLogicHelper::checkDigit_HWE(numberSeq);
                numberSequence =  numberSeq + int2Str(checkDigit);
            }
            else
            {
                numberSequence =  numberSeq;
            }
            
        }
        
        return numberSequence;
    }

    /// <summary>
    /// Dialog method to capture runtime user inputs for customer details
    /// </summary>
    /// <returns>dialog</returns>
    public Object dialog()
    {
        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            dialog = super();
            dialog.caption("@SYS59934");

            dlgCreateCustomer        = dialog.addField(extendedTypeStr(CustAccount), "@SYS124832");
            dlgCreateCustomer.enabled(false);

            dlgBusinessUnit = dialog.addField(extendedTypeStr(METBusinessUnitTableRefRecId), "@SYS313109");
            dlgBusinessUnit.registerOverrideMethod(methodStr(FormReferenceControl, lookupReference),
                methodStr(METCreateCustNumSeqDialog, businessUnitLookup), this);

            FormBuildReferenceGroupControl businessUnitControl;

            businessUnitControl    = dlgBusinessUnit.control();

            if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
            {
                businessUnitControl.mandatory(true);
            }
            else
            {
                businessUnitControl.enabled(false);
            }
        }
        return dialog;
    }

    /// <summary>
    /// Validate the controls
    /// </summary>
    /// <param name = "_calledFrom">_calledFrom</param>
    /// <returns>boolean value</returns>
    public boolean validate(Object _calledFrom = null)
    {
        boolean     ret;
        ret         = super(_calledFrom);

        if (METCustParameters::Find().BusinessUnit == NoYes::Yes)
        {
            if (!metBusinessUnitRecId)
            {
                ret = checkFailed("@MET:METBusinessUnitValidate");
            }
        }
        return ret;
    }

/// <summary>
/// Retrieves values from the dialog after it is completed.
/// </summary>
/// <returns>true if values are retrieved successfully; otherwise, false.</returns>
public boolean getFromDialog()
{
    boolean ret = true;
    
    if (dlgBusinessUnit)
    {
        metBusinessUnitRecId     = dlgBusinessUnit.value();
    }
    
    return ret;
}

    public RefRecId getBusinessUnitRecId()
    {
        metBusinessUnitRecId = dlgBusinessUnit.value();

        return metBusinessUnitRecId;
    }

/// <summary>
/// Get the custTable
/// </summary>
/// <param name = "_custTable">custTable</param>
/// <returns>custTable</returns>
public CustTable parmCustTable(CustTable _custTable = custTable)
{
    custTable = _custTable;
    
    return custTable;
}

/// <summary>
/// look up for Business unit
/// </summary>
/// <param name = "_lookup">Form reference control</param>
/// <returns>Business unit</returns>
public Common businessUnitLookup(FormReferenceControl _lookup)
{
    return METBusinessUnit::lookupReferenceType(_lookup);
}

/// <summary>
/// Run in the new session
/// </summary>
/// <returns>false</returns>
protected boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Construct the METCreateCustNumSeqDialog
/// </summary>
/// <returns>METCreateCustNumSeqDialog</returns>
public static METCreateCustNumSeqDialog construct()
{
    return new METCreateCustNumSeqDialog();
}
